head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.isurCd = "";
scwin.isurNm = "";
scwin.inputRnd = "";
scwin.displayFlag = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — readSync 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        scwin.isurCd = $c.data.getParameter("isurCd");
        scwin.isurNm = $c.data.getParameter("isurNm");
        scwin.inputRnd = $c.data.getParameter("inputRnd");
        scwin.displayFlag = $c.data.getParameter("displayFlag");

        if(scwin.displayFlag === "U") {

        ibx_isurCd.setDisabled(true);
        ibx_comNm.setDisabled(true);

        ibx_isurCd.setValue(scwin.isurCd);
        ibx_comNm.setValue(scwin.isurNm);
        img_coSearch.setDisabled(true);

        btn_save.setDisabled(true);

        scwin.readSync(); // 상세조회

        } else {

        btn_update.setDisabled(true);
        btn_delete.setDisabled(true)
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05962.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @Event
 * @name btn_close_onclick
 * @description btn_close_onclick event
 * @returns {void}
 * @hidden N
 */
scwin.btn_close_onclick = function (e) {
    try {
        $c.win.closeAllPopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05962.btn_close_onclick" });
    }
};

/**
 * @method
 * @Event
 * @name btn_save_onclick
 * @description 저장버튼 event
 * @returns {void}
 * @hidden N
 */
scwin.btn_save_onclick = function (e) {
    try {
        scwin.checkForm();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05962.btn_save_onclick" });
    }
};

/**
 * @method
 * @Event
 * @name btn_update_onclick
 * @description 수정버튼 event
 * @returns {void}
 * @hidden N
 */
scwin.btn_update_onclick = function (e) {
    try {
        scwin.checkForm();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05962.btn_update_onclick" });
    }
};

/**
 * @method
 * @Event
 * @name btn_delete_onclick
 * @description 삭제버튼 event
 * @returns {void}
 * @hidden N
 */
scwin.btn_delete_onclick = function (e) {
    try {
        scwin.delete();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05962.btn_delete_onclick" });
    }
};

/**
 * @method
 * @name img_coSearch_onclick
 * @description 발행회사검색(팝업)호출
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_coSearch_onclick = function (e) {
    try {
        $c.cm.isurcdSearch(ibx_isurCd, ibx_comNm);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05962.img_coSearch_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @func
 * @name scwin.readSync
 * @description 상세조회
 * @returns {void}
 * @hidden N
 */
scwin.readSync = async function() {

    dma_searchlReq.set("isurCd",scwin.isurCd);
    dma_searchlReq.set("inputRnd",scwin.inputRnd);

    const sbmOptions = {
        id : "sbm_hdnchamp",
        action : "/api/listing/lstmgt/sect-authqual/select-one-hdnchamp",
        method : "get",
        ref : "dma_searchlReq",
        target : "dma_hdnchampReqRes=body",
        submitDoneHandler : (e) => {
        },
        isProcessMsg : false
    };

    const res =  await $c.sbm.executeDynamic(sbmOptions);
    // if (res.responseJSON.success == true) {

    // }
}

/**
 * @method
 * @func
 * @name scwin.readSync
 * @description 저장
 * @returns {void}
 * @hidden N
 */
scwin.save = async function() {

    let sText = "";
    if(scwin.displayFlag === "C") {
        sText = "[저장]";
    } else {
        sText = "[수정]";
    }

    const rtn = await $c.win.confirm(sText+" 처리를 하시겠습니까?");
    if(!rtn) return;

    dma_hdnchampReqRes.set("isurCd",ibx_isurCd.getValue());
    if(scwin.displayFlag === "C") {
        dma_hdnchampReqRes.set("inputRnd", "");
    } else {
        dma_hdnchampReqRes.set("inputRnd", scwin.inputRnd);
    }

    const sbmOptions = {
        id : "sbm_saveHdnchamp",
        action : "/api/listing/lstmgt/sect-authqual/save-hdnchamp",
        method : "post",
        ref : "dma_hdnchampReqRes",
        isProcessMsg : true
    };

    const res =  await $c.sbm.executeDynamic(sbmOptions);
    if (res.responseJSON.success === true) {
        await $c.win.alert(sText+' 처리 성공했습니다.');
        $c.win.closeAllPopup();
    }
}

/**
 * @method
 * @func
 * @name scwin.readSync
 * @description 삭제
 * @returns {void}
 * @hidden N
 */
scwin.delete = async function() {

    const rtn = await $c.win.confirm('[삭제] 처리를 하시겠습니까?');
    if(!rtn) return;

    dma_hdnchampReqRes.set("isurCd",ibx_isurCd.getValue());
    dma_hdnchampReqRes.set("inputRnd", dma_hdnchampReqRes.get("inputRnd"));

    const sbmOptions = {
        id : "sbm_saveHdnchamp",
        action : "/api/listing/lstmgt/sect-authqual/delete-hdnchamp",
        method : "post",
        ref : "dma_hdnchampReqRes",
        isProcessMsg : true
    };

    const res =  await $c.sbm.executeDynamic(sbmOptions);
    if (res.responseJSON.success === true) {
        await $c.win.alert('[삭제] 처리 성공했습니다.');
        $c.win.closeAllPopup();
    }
}

///////// 5. 일반/업무 함수 영역 /////////
    /**
     * @method
     * @func
     * @name fn_CheckForm
     * @description : 저장,수정시 validation
     * @returns {void}
     * @hidden N
     */
scwin.checkForm = async function (flag) {

    if(ibx_comNm.getValue() === "") {
        $c.win.alert("[회사명]를 입력하세요.");
        ibx_comNm.focus();
        return false;
    }
    const options = {
            validateType : "alert",
            checkType : "single",
            focus : true,
            fields : {
                ibx_sectAhthQualContn   : { required : true,  name : "[라이징스타 인증자격]을 입력하세요." },
                ibx_sectAhthInstNm    : { required : true,  name : "라이징스타 인증기관]을 입력하세요." },
                ibx_designDd1    : { required : true,  name : "[라이징스타 지정일자]를 입력하세요." },
            }
    };

    const res = await $c.validate.validateDataCollect(grp_InputForm, options);

    if(res){ scwin.save() };

}
